package org.fribok.bookkeeping.dataformat;
import org.junit.jupiter.api.Test;import se.swedsoft.bookkeeping.data.*;import se.swedsoft.bookkeeping.data.base.*;import se.swedsoft.bookkeeping.data.common.*;import java.io.*;import java.math.*;import java.nio.charset.*;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class CustomerInvoiceStagingConverterTest{
 @Test void roundTripsInvoiceSnapshotRowsAccountsAddressesAndVoucher()throws Exception{try(Connection legacy=conn("invoice_legacy");Connection target=conn("invoice_target")){schema(legacy);new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(target,NormalizedSchemaMigrations.load());SSNewCompany company=new SSNewCompany();company.setId(1);insertCompany(legacy,company);SSNewProject project=new SSNewProject("P1","Project",null);insertScoped(legacy,"tbl_project","project","P1",project);SSNewResultUnit result=new SSNewResultUnit("R1","Result");insertScoped(legacy,"tbl_resultunit","resultunit","R1",result);SSInvoice invoice=invoice();try(var p=legacy.prepareStatement("INSERT INTO tbl_invoice (id,number,invoice,companyid) VALUES (?,?,?,?)")){p.setInt(1,77);p.setInt(2,invoice.getNumber());p.setObject(3,invoice);p.setInt(4,1);p.executeUpdate();legacy.commit();}new AccountingCoreStagingConverter().convert(legacy,target);new AccountingDimensionsStagingConverter().convert(legacy,target);var converted=new CustomerInvoiceStagingConverter().convert(legacy,target);assertThat(converted.sourceFingerprint()).isEqualTo(converted.destinationFingerprint());assertThat(converted.invoices()).isEqualTo(1);assertThat(converted.addresses()).isEqualTo(2);assertThat(converted.defaultAccounts()).isEqualTo(2);assertThat(converted.rows()).isEqualTo(2);assertThat(converted.vouchers()).isEqualTo(1);assertThat(converted.voucherRows()).isEqualTo(1);assertThat(converted.daylightSavingOverlapResolutions()).isEqualTo(1);}}
 @Test void rejectsTableAndObjectNumberMismatch()throws Exception{try(Connection legacy=conn("invoice_bad_legacy");Connection target=conn("invoice_bad_target")){schema(legacy);new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(target,NormalizedSchemaMigrations.load());SSNewCompany c=new SSNewCompany();c.setId(1);insertCompany(legacy,c);new AccountingCoreStagingConverter().convert(legacy,target);SSInvoice x=new SSInvoice();x.setNumber(2);try(var p=legacy.prepareStatement("INSERT INTO tbl_invoice (id,number,invoice,companyid) VALUES (?,?,?,?)")){p.setInt(1,77);p.setInt(2,1);p.setObject(3,x);p.setInt(4,1);p.executeUpdate();legacy.commit();}assertThatThrownBy(()->new CustomerInvoiceStagingConverter().convert(legacy,target)).isInstanceOf(SQLException.class).hasMessageContaining("Invoice key/object mismatch");}}
 private static SSInvoice invoice(){SSInvoice x=new SSInvoice();x.setNumber(42);x.setLocalDate(LocalDate.of(2026,10,25));x.setLocalDueDate(null);x.setCustomerNr("K1");x.setCustomerName("");x.setOurContactPerson("Vi");x.setYourContactPerson("Ni");x.setDelayInterest(null);x.setCurrency(new SSCurrency("EUR","Euro"));x.getCurrency().setExchangeRate(new BigDecimal("11.25"));x.setPaymentTerm(new SSPaymentTerm("30","30 dagar"));x.setDeliveryTerm(new SSDeliveryTerm("FK","Fritt"));x.setDeliveryWay(new SSDeliveryWay("P","Post"));x.setTaxFree(false);x.setText("");x.setTaxRate1(new BigDecimal("25.00"));x.setTaxRate2(null);x.setTaxRate3(new BigDecimal("6"));x.setEuSaleCommodity(true);x.setEuSaleYhirdPartCommodity(false);x.setPrinted(true);x.setType(null);x.setCurrencyRate(new BigDecimal("1.12300"));x.setYourOrderNumber("O1");x.setOCRNumber(null);x.setEntered(false);x.setNumRemainders(-1);x.setInterestInvoiced(true);x.setStockInfluencing(false);x.setOrderNumbers("");x.setInvoiceAddress(new SSAddress("F","Gata","","1","Ort","SE"));x.setDeliveryAddress(new SSAddress("L","Väg","C/O","2","Ort2","SE"));Map<SSDefaultAccount,Integer>a=new HashMap<>();a.put(SSDefaultAccount.Sales,3001);a.put(SSDefaultAccount.Tax1,null);x.setDefaultAccounts(a);SSSaleRow r1=new SSSaleRow();r1.setProductNr("A");r1.setDescription("");r1.setUnitprice(new BigDecimal("10.125"));r1.setQuantity(new BigDecimal("-2.50"));r1.setUnit(new SSUnit("st","styck"));r1.setDiscount(null);r1.setTaxCode(SSTaxCode.TAXRATE_1);r1.setAccountNr(3001);r1.setProjectNr("P1");r1.setResultUnitNr("R1");SSSaleRow r2=new SSSaleRow();r2.setProductNr(null);r2.setDescription(null);r2.setQuantity(null);x.setRows(r1,r2);SSVoucher v=new SSVoucher(0);v.setLocalDate(null);v.setDescription("");SSVoucherRow vr=new SSVoucherRow();vr.setAccountNr(null);vr.setDebet(new BigDecimal("10.00"));vr.setLocalEditedDate(LocalDateTime.of(2026,10,25,2,30));vr.setEditedSignature("vb");vr.setCrossed(true);v.addVoucherRow(vr);x.setVoucher(v);return x;}
 private static Connection conn(String n)throws Exception{Class.forName("org.hsqldb.jdbcDriver");Connection c=DriverManager.getConnection("jdbc:hsqldb:mem:"+n+"_"+UUID.randomUUID(),"sa","");c.setAutoCommit(false);return c;}private static void schema(Connection c)throws Exception{try(InputStream in=CustomerInvoiceStagingConverterTest.class.getResourceAsStream("/sql/create_tables.sql")){String sql=new String(Objects.requireNonNull(in).readAllBytes(),StandardCharsets.UTF_8);try(var p=c.createStatement()){for(String y:sql.split(";"))if(!y.isBlank())p.execute(y.trim());}c.commit();}}private static void insertCompany(Connection c,SSNewCompany x)throws Exception{try(var p=c.prepareStatement("INSERT INTO tbl_company (id,company) VALUES (?,?)")){p.setInt(1,x.getId());p.setObject(2,x);p.executeUpdate();c.commit();}}private static void insertScoped(Connection c,String t,String col,String key,Object x)throws Exception{try(var p=c.prepareStatement("INSERT INTO "+t+" (number,"+col+",companyid) VALUES (?,?,1)")){p.setString(1,key);p.setObject(2,x);p.executeUpdate();c.commit();}}
}
